PAY = ['key:Escape', 'user:owner', 'click:menutop:People & Payroll', 'click:menuleaf:Staff']
chapter(18, 'Staff, leave and payroll', 'Add a new room attendant, read the roster and attendance, request and approve leave, read the payroll register and payslips, record a salary advance, and see what an attendant sees under My shifts & pay.',
        'Meera (Manager)', 'manager', menu='People & Payroll > Staff')
step('Meera, the Manager, is on Modules Home. People & Payroll has two tiles: My shifts & pay for everyone and Staff & payroll for those who manage staff.', 'Every employee sees their own shifts and pay; only managers see everybody.', target='sel:.fit-home-grid', auto=['key:Escape', 'user:manager'], action='read', expect='Modules Home for Meera.', check="ctx.uid==='manager'")
tile('People & Payroll', 'Click the People & Payroll tile.', 'The two staff screens are listed.', expect='The People & Payroll page opens with two tiles.')
leaf('People & Payroll', 'Staff', 'Click the Staff & payroll tile.', 'It holds the register, the roster, attendance, leave and, for the Owner, payroll.', expect='Staff & payroll opens on the Staff tab.', check="ctx.page==='staff'")
read('The Staff tab lists the team by department: Management, Front office, Housekeeping, Maintenance, Kitchen, Security and Accounts. Each person has Edit and Exit; Add staff member creates a new one.', 'The register is the source for the roster, the attendance and the payroll.', target='btn:Add staff member', expect='The staff register by department.')
click('btn:Add staff member', 'Click Add staff member. Sunil Pawar joins as a room attendant.', 'A new joiner is added once and then appears on the roster.', expect='The Add staff member dialog opens.', check="has('Full name')")
step('Type the full name Sunil Pawar and choose the department Housekeeping. Then choose the designation, the default shift Morning and the weekly off Sunday.', 'The department and designation decide the pay group and the statutory slabs.', target='field:Full name',
     auto=['type:field:Full name|Sunil Pawar', 'select:field:Department|Housekeeping', 'select:field:Designation|Room', 'select:field:Default shift|Morning', 'select:field:Weekly off|Sun'], action='type', expect='The form is filled for Sunil Pawar.')
click('modalbtn:Add staff member', 'Click Add staff member.', 'The new attendant appears in Housekeeping and can be put on the roster.', expect='Sunil Pawar is added.')
click('tab:Roster', 'Open the Roster tab.', 'The weekly roster shows each person\'s shift for each day; Change edits a cell and Copy to next week repeats the pattern.', expect='The weekly roster opens.')
click('tab:Attendance', 'Open the Attendance tab.', 'The register for today lists everybody; Mark records present, absent, half day or off.', expect='The attendance register of 26 Oct opens.')
step('Kavya, a room attendant, asks for leave. She opens My shifts & pay and clicks Request leave.', 'An employee asks for leave on the phone or the desk; nobody can approve their own leave.', target='dialog:',
     auto=['key:Escape', 'user:housekeeper2', 'click:menutop:People & Payroll', 'click:btn:Request leave'], action='click', expect='The Add Leave dialog opens.', check="has('Add Leave')")
step('Choose the approver Meera, the category Casual leave, 30 Oct as the day, and the reason Family function.', 'HCC checks the entitlement and the staff already on leave that day.', target='field:Reason', auto=['select:field:Approver|Meera', 'type:field:Leave From|2026-10-30', 'type:field:Leave To|2026-10-30', 'type:field:Reason|Family function'], action='type', expect='The leave request is filled.')
click('modalbtn:Add Leave', 'Click Add Leave.', 'The request goes to Meera.', expect='The leave request is saved.')
step('Meera opens Staff & payroll, the Leave tab and its Approvals. She approves Kavya\'s request.', 'The approver sees the entitlement left and how many are on leave that day before agreeing.', target='btn:Approve',
     auto=['key:Escape', 'user:manager', 'click:menutop:People & Payroll', 'click:menuleaf:Staff', 'click:tab:Leave', 'click:btn:Approvals'], action='click', expect='The leave approvals list shows Approve and Reject.', check="has('Leave approvals')")
click('btnin:Kavya|Approve', 'Click Approve on Kavya\'s request.', 'The quota is checked again at approval; the leave appears on the calendar and in the payroll days.', expect='The leave is approved.')
step('Sagar, the Owner, opens the Payroll tab. The months April to September are locked runs.', 'Payroll is the Owner\'s screen: pay days come from the attendance and the leave.', target='sel:main h2', auto=PAY + ['click:tab:Payroll'], action='click', expect='The monthly payroll register opens on September.', check="has('Monthly payroll')", allowError=True)
read('Each row is one employee with the pay days, the earnings, the PF, ESIC and professional-tax deductions and the net pay. The month is locked; Unlock reopens it for a correction. Register CSV and Excel, the bank transfer file and the PF / ESIC / PT statement are exports for the accountant and the bank. October cannot be run yet, because a month is processed after it ends.', 'A locked month cannot be changed by mistake.', target='btn:Bank transfer file', expect='The payroll register of September.')
click('btn:Payslip', 'Click Payslip on a row.', 'The payslip is the printout the employee takes home.', expect='The payslip opens.')
step('Close the payslip and open the Advances tab. Click Record advance for the new attendant Sunil Pawar. Ravi already has an open advance, and HCC allows one open advance per person.', 'A salary advance is paid now and recovered from the next payroll.', target='dialog:', auto=['key:Escape', 'click:tab:Advances', 'click:btn:Record advance'], action='click', expect='The Record advance dialog opens.', check="has('Monthly recovery')")
step('Choose the staff member Sunil Pawar, the amount 2000 rupees, recovery from October 2026 payroll, paid from drawer cash, and the reason Festival advance.', 'The advance is recovered automatically, so the payroll needs no manual calculation.', target='field:Amount', auto=['select:field:Staff member|Sunil', 'type:field:Amount|2000', 'type:field:Reason|Festival advance'], action='type', expect='The advance is filled.')
click('modalbtn:Record advance', 'Click Record advance.', 'The cash leaves the drawer and the amount shows against Sunil until recovered.', expect='The advance is recorded.')
click('tab:Full and final', 'Open the Full and final tab.', 'When a person leaves, the final settlement of pay, leave and advances is worked out here; nobody is leaving today.', expect='The page says nobody is waiting for a settlement.')
click('tab:Statutory rates', 'Open the Statutory rates tab.', 'PF, ESIC and professional-tax rates are versioned, so an old payroll is never recalculated with a new rate.', expect='The statutory rate versions are listed.')
step('Ravi opens People & Payroll. He sees only My shifts & pay: today\'s shift, his week, his leave balance and his payslip.', 'Staff see only their own pay; housekeeping and maintenance see no hotel money.', target='sel:main h1', auto=['key:Escape', 'user:housekeeper', 'click:menutop:People & Payroll'], action='click', expect='My shifts & pay opens for Ravi.', check="ctx.page==='my-hr'")
read('The page shows the Morning shift 07:00 to 15:00, a Check in now button for attendance, the week, the month so far, the leave quota of the financial year and the payslip of September with View / print and Payslip PDF.', 'This page is on the phone for every employee.', target='btn:Check in now', expect='The My shifts & pay page.')
